names=[("التكوين","تك"),("الخروج","خر"),("اللاويين","لا"),("العدد","عد"),("التثنية","تث"),("يشوع","يش"),("القضاة","قض"),("راعوث","را"),("صموئيل الأول","١صم"),("صموئيل الثاني","٢صم"),("الملوك الأول","١مل"),("الملوك الثاني","٢مل"),("أخبار الأيام الأول","١أخ"),("أخبار الأيام الثاني","٢أخ"),("عزرا","عز"),("نحميا","نح"),("أستير","أس"),("أيوب","أي"),("المزامير","مز"),("الأمثال","أم"),("الجامعة","جا"),("نشيد الأنشاد","نش"),("إشعياء","إش"),("إرميا","إر"),("مراثي إرميا","مرا"),("حزقيال","حز"),("دانيال","دا"),("هوشع","هو"),("يوئيل","يؤ"),("عاموس","عا"),("عوبديا","عو"),("يونان","يون"),("ميخا","مي"),("ناحوم","نا"),("حبقوق","حب"),("صفنيا","صف"),("حجي","حج"),("زكريا","زك"),("ملاخي","ملا"),
("إنجيل متى","مت"),("إنجيل مرقس","مر"),("إنجيل لوقا","لو"),("إنجيل يوحنا","يو"),("أعمال الرسل","أع"),("رومية","رو"),("كورنثوس الأولى","١كو"),("كورنثوس الثانية","٢كو"),("غلاطية","غل"),("أفسس","أف"),("فيلبي","في"),("كولوسي","كو"),("تسالونيكي الأولى","١تس"),("تسالونيكي الثانية","٢تس"),("تيموثاوس الأولى","١تي"),("تيموثاوس الثانية","٢تي"),("تيطس","تي"),("فليمون","فل"),("العبرانيين","عب"),("يعقوب","يع"),("بطرس الأولى","١بط"),("بطرس الثانية","٢بط"),("يوحنا الأولى","١يو"),("يوحنا الثانية","٢يو"),("يوحنا الثالثة","٣يو"),("يهوذا","يه"),("الرؤيا","رؤ")]
groups=[("torah","التوراة",5),("history","الأسفار التاريخية",12),("poetry","الشعر والحكمة",5),("major","الأنبياء الكبار",5),("minor","الأنبياء الصغار",12),("gospels","الأناجيل",4),("acts","التاريخ",1),("paul","رسائل بولس",13),("general","الرسائل العامة",8),("prophecy","النبوة",1)]
g=[]
for key,ar,n in groups: g+= [(key,ar)]*n
slug={'Gen':'genesis','Exod':'exodus','Lev':'leviticus','Num':'numbers','Deut':'deuteronomy','Josh':'joshua','Judg':'judges','Ruth':'ruth','1Sam':'1-samuel','2Sam':'2-samuel','1Kgs':'1-kings','2Kgs':'2-kings','1Chr':'1-chronicles','2Chr':'2-chronicles','Ezra':'ezra','Neh':'nehemiah','Esth':'esther','Job':'job','Ps':'psalms','Prov':'proverbs','Eccl':'ecclesiastes','Song':'song-of-songs','Isa':'isaiah','Jer':'jeremiah','Lam':'lamentations','Ezek':'ezekiel','Dan':'daniel','Hos':'hosea','Joel':'joel','Amos':'amos','Obad':'obadiah','Jonah':'jonah','Mic':'micah','Nah':'nahum','Hab':'habakkuk','Zeph':'zephaniah','Hag':'haggai','Zech':'zechariah','Mal':'malachi','Matt':'matthew','Mark':'mark','Luke':'luke','John':'john','Acts':'acts','Rom':'romans','1Cor':'1-corinthians','2Cor':'2-corinthians','Gal':'galatians','Eph':'ephesians','Phil':'philippians','Col':'colossians','1Thess':'1-thessalonians','2Thess':'2-thessalonians','1Tim':'1-timothy','2Tim':'2-timothy','Titus':'titus','Phlm':'philemon','Heb':'hebrews','Jas':'james','1Pet':'1-peter','2Pet':'2-peter','1John':'1-john','2John':'2-john','3John':'3-john','Jude':'jude','Rev':'revelation'}
out=[]
for i,b in enumerate(ids):
    d=json.load(open(f'data/bible/{b}.json',encoding='utf-8'))
    out.append({'id':b,'slug':slug[b],'name':names[i][0],'abbr':names[i][1],'testament':'ot' if i<39 else 'nt','group':g[i][0],'groupName':g[i][1],'order':i+1,'chapters':len(d['chapters']),'verses':[len(c['verses']) for c in d['chapters']]})
json.dump(out,open('data/books.json','w',encoding='utf-8'),ensure_ascii=False,indent=0)
print(len(out))
